import React, { useState } from "react";

export default function AdminDashboard({ reports, ngoList, token, setMsg }) {
  const [approveMsg, setApproveMsg] = useState("");
  const [ngos, setNgos] = useState(null);
  const [eventStats, setEventStats] = useState(null);

  function approveNGO(id) {
    setApproveMsg("Approve action is not available in demo.");
  }

  return (
    <div className="panel">
      <h3>Admin Reports</h3>

      <div className="cards">
        <div className="stat-card">
          <div className="stat-num">
            {reports
              ? reports.donations
                ? reports.donations.reduce(
                    (s, d) => s + parseFloat(d.amount || 0),
                    0
                  )
                : 0
              : "-"}
          </div>
          <div className="stat-label">Total Donation Amount (₹)</div>
        </div>

        <div className="stat-card">
          <div className="stat-num">
            {reports ? (reports.volunteers ? reports.volunteers.length : 0) : "-"}
          </div>
          <div className="stat-label">Total Volunteers</div>
        </div>

        <div className="stat-card">
          <div className="stat-num">
            {reports ? (reports.feedbacks ? reports.feedbacks.length : 0) : "-"}
          </div>
          <div className="stat-label">Feedbacks</div>
        </div>
      </div>

      <h4>Approve NGOs</h4>

      <div style={{ marginTop: 12 }}>
        <button
          onClick={async () => {
            if (!token) {
              setMsg("Login as admin to view NGOs");
              return;
            }
            try {
              const res = await fetch(
                (process.env.REACT_APP_API || "http://localhost:4000") +
                  "/api/actions/ngos",
                { headers: { Authorization: `Bearer ${token}` } }
              );
              if (!res.ok) throw new Error("Failed to load NGOs");
              const d = await res.json();
              setNgos(d.ngos || []);
            } catch (err) {
              console.error(err);
              setMsg(err.message || "Error loading NGOs");
            }
          }}
        >
          View Registered NGOs
        </button>

        <button
          style={{ marginLeft: 8 }}
          onClick={async () => {
            if (!token) {
              setMsg("Login as admin to view events");
              return;
            }
            try {
              const res = await fetch(
                (process.env.REACT_APP_API || "http://localhost:4000") +
                  "/api/actions/registered-events",
                { headers: { Authorization: `Bearer ${token}` } }
              );
              if (!res.ok) throw new Error("Failed to load registered events");
              const d = await res.json();
              setEventStats(d.events || []);
            } catch (err) {
              console.error(err);
              setMsg(err.message || "Error loading events");
            }
          }}
        >
          View Registered Events
        </button>

        <button
          style={{ marginLeft: 8 }}
          onClick={async () => {
            if (!token) {
              setMsg("Login as admin to view event stats");
              return;
            }
            try {
              const res = await fetch(
                (process.env.REACT_APP_API || "http://localhost:4000") +
                  "/api/actions/event-stats",
                { headers: { Authorization: `Bearer ${token}` } }
              );
              if (!res.ok) throw new Error("Failed to load event stats");
              const d = await res.json();
              setEventStats(d.events || []);
            } catch (err) {
              console.error(err);
              setMsg(err.message || "Error loading event stats");
            }
          }}
        >
          View Event Stats
        </button>
      </div>

      {/* ----------- NEW LAYOUT: LEFT = NGO LIST | RIGHT = EVENT STATISTICS ----------- */}
      <div style={{ display: "flex", gap: 16 }}>
        {/* LEFT SIDE – NGO LIST */}
        <div style={{ flex: 1 }}>
          {ngos ? (
            ngos.length ? (
              <div style={{ display: "grid", gap: 8 }}>
                {ngos.map((n) => (
                  <div
                    key={n.id}
                    style={{
                      padding: 8,
                      background: "#fff",
                      borderRadius: 8,
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                    }}
                  >
                    <div>
                      <strong>{n.name}</strong>
                      <div style={{ fontSize: 13, color: "#666" }}>
                        {n.email}
                      </div>
                    </div>

                    <button
                      onClick={async () => {
                        if (!token) {
                          setMsg("Login as admin");
                          return;
                        }
                        try {
                          const res = await fetch(
                            (process.env.REACT_APP_API ||
                              "http://localhost:4000") +
                              "/api/actions/ngo/" +
                              n.id,
                            { headers: { Authorization: `Bearer ${token}` } }
                          );
                          if (!res.ok)
                            throw new Error("Failed to load NGO details");
                          const d = await res.json();
                          setEventStats(d.events || []);
                        } catch (err) {
                          console.error(err);
                          setMsg(err.message || "Error loading NGO details");
                        }
                      }}
                    >
                      View Details
                    </button>
                  </div>
                ))}
              </div>
            ) : (
              <p>No NGOs registered.</p>
            )
          ) : (
            <p>Loading NGOs...</p>
          )}
        </div>

        {/* RIGHT SIDE – EVENT STATISTICS (replacing old Selected NGO section) */}
        <div style={{ width: 420 }}>
          <h4>Event Statistics</h4>

          {eventStats && eventStats.length ? (
            eventStats.map((ev) => (
              <div
                key={ev.id}
                style={{
                  display: "flex",
                  gap: 12,
                  alignItems: "center",
                  padding: 8,
                  background: "#fff",
                  borderRadius: 8,
                  marginBottom: 8,
                }}
              >
                <img
                  src={ev.image_url || "https://via.placeholder.com/120x80"}
                  style={{
                    width: 100,
                    height: 64,
                    objectFit: "cover",
                    borderRadius: 6,
                  }}
                />

                <div style={{ flex: 1 }}>
                  <div style={{ fontWeight: 600 }}>{ev.title}</div>
                  <div style={{ fontSize: 13, color: "#666" }}>
                    Volunteers: {ev.volunteers_count} — Donations: ₹
                    {ev.donations_sum}
                  </div>
                </div>
              </div>
            ))
          ) : (
            <div>Click any NGO to view its events</div>
          )}
        </div>
      </div>

      {approveMsg && <p className="msg">{approveMsg}</p>}
    </div>
  );
}
